        V("bato-l17", "batò", "stone", say="BA-toQ", group="words", note="From the book's sentence: ng batò = with stones"),
        V("kuya-l17", "kuya", "elder brother", group="words"),
        V("mag-aral-m17", "mag-áral", "to learn", say="mag-A-ral", pos="verb", group="more", note="Lesson 14 glosses mag-áral as to study"),
        V("lumakad-m17", "lumákad", "go", say="lu-MA-kad", pos="verb", group="more", note="From: Maáarì kayóng lumákad na. = You (plural) may go already."),
        V("maligo-m17", "maligò", "take a bath", say="ma-LI-goQ", pos="verb", group="more", note="From: Kailángang maligò tayo araw-araw. = We need to take a bath everyday."),
        V("araw-araw-m17", "araw-araw", "everyday", pos="adv", group="more", note="Lesson 15 prints áraw-áraw. From: Kailángang maligò tayo araw-araw. = We need to take a bath everyday."),
        V("tayo-m17", "tayo", "we", pos="pron", group="more", note="Lesson 6 prints táyo. From: Kailángang maligò tayo araw-araw. = We need to take a bath everyday."),
        V("aralin-m17", "arálin", "learn", say="a-RA-lin", pos="verb", group="more", note="From: Gustó kong arálin ang Tagálog. = I want to learn Tagalog."),
        V("sulatin-m17", "sulatín", "be written", say="su-la-TIN", pos="verb", group="more", note="Lesson 15 prints sulátin (to write). From: Dapat sulatín ni Peter ang kanyang kuwénto ngayóng gabi. = His/Her story must be written by Peter tonight."),
        V("ngayong-gabi-m17", "ngayóng gabi", "tonight", say="nga-YONG ga-bi", pos="phrase", group="more", note="From: Dapat sulatín ni Peter ang kanyang kuwénto ngayóng gabi. = His/Her story must be written by Peter tonight."),
        V("mo-by-you-m17", "mo", "by you", pos="pron", group="more", note="Lesson 8 glosses mo as your. From: Maáarì bang linísin mo ang aking sapátos? = Could my shoes be cleaned by you?"),
        V("aking-m17", "aking", "my", pos="pron", group="more", note="Lesson 15 prints áking. From: Dapat akóng sumúlat sa aking kaibígan sa Estados Unidos. = I must write to my friend in the United States."),
        V("estados-unidos-m17", "Estados Unidos", "the United States", pos="noun", group="more", note="Lesson 4 prints Estados Unídos. From: Dapat akóng sumúlat sa aking kaibígan sa Estados Unidos. = I must write to my friend in the United States."),
        V("iyong-m17", "iyong", "your", pos="pron", group="more", note="iyó + -ng. From: Maáarì akong maglínis ng iyong sapátos. = I can clean your shoes."),
        V("kumain-m17", "kumain", "to eat", pos="verb", group="more", note="Lesson 2 prints kumáin. From: Áyaw siyáng kumain ng balút. = He/She does not like to eat balut."),
        V("balut-m17", "balut", "steamed duck embryo", pos="noun", group="more", note="The vocabulary list prints balút. From: He/She does not like balut (steamed duck embryo) to be eaten."),
